import assert from 'node:assert/strict';
import { readFile,writeFile } from 'node:fs/promises';
import { chromium } from '/root/workspace/ha-lovelace-extended/experiments/minimum-card-contract/node_modules/playwright/index.mjs';
import {tokens,createPage,base} from './common.mjs';
const area='/root/research/ha-lovelace-extended/implement-complete-desk-composition';
const fixtures=JSON.parse(await readFile('/root/workspace/ha-lovelace-extended/candidates/fixed-composition-card/test/fixtures.json','utf8'));
const auth=await tokens();
for(const [entity,state] of Object.entries(fixtures)) {
 const r=await fetch(base+'/api/states/'+entity,{method:'POST',headers:{Authorization:'Bearer '+auth.access_token,'Content-Type':'application/json'},body:JSON.stringify(state)});
 assert.ok(r.ok,'Synthetic fixture creation');
}
const browser=await chromium.launch();
try {
 const {page}=await createPage(browser,auth);
 let serviceFrames=0,serviceRequests=0;
 page.on('websocket',ws=>ws.on('framesent',frame=>{try{if(JSON.parse(frame.payload).type==='call_service')serviceFrames++;}catch{}}));
 await page.route('**/*',async route=>{
  const url=new URL(route.request().url());
  if(url.hostname!=='127.0.0.1') return route.abort();
  if(/^\/api\/services(?:\/|$)/.test(decodeURIComponent(url.pathname))) {serviceRequests++;return route.abort();}
  return route.continue();
 });
 await page.goto(base+'/lovelace/0');
 await page.waitForFunction(()=>!!document.querySelector('home-assistant')?.hass?.states?.['cover.fcc_primary']);
 const results=await page.evaluate(async()=>{
  const hass=document.querySelector('home-assistant').hass;
  const call=(domain,service,entity,data={})=>hass.callWS({type:'call_service',domain,service,target:{entity_id:entity},service_data:data});
  const allowed=[];
  for(const service of ['open_cover','close_cover','stop_cover']) {await call('cover',service,'cover.fcc_primary');allowed.push(service);}
  await call('cover','set_cover_position','cover.fcc_alternate',{position:37});allowed.push('set_cover_position');
  for(let n=1;n<=3;n++){await call('button','press',`button.fcc_memory_${n}`);allowed.push(`memory_${n}`);}
  let denied=0;
  for(const [domain,service,entity,data] of [['cover','open_cover','cover.real',{}],['button','press','button.real',{}],['cover','unlock','cover.fcc_primary',{}],['cover','set_cover_position','cover.fcc_primary',{position:101}],['cover','open_cover','cover.fcc_primary',{extra:true}],['cover','open_cover',['cover.fcc_primary','cover.fcc_alternate'],{}]]) {
   try{await call(domain,service,entity,data);throw new Error('Unexpected allow');}catch(e){if(e.message==='Unexpected allow')throw e;denied++;}
  }
  let rest=false,xhr=false;
  try{await fetch('/api/services/cover/open_cover',{method:'POST'});}catch{rest=true;}
  try{const x=new XMLHttpRequest();x.open('POST','/api/services/button/press');x.send('{}');}catch{xhr=true;}
  const before=hass.states['cover.fcc_primary'];
  return {allowed,denied,restBlocked:rest,xhrBlocked:xhr,events:fccLab.events,blocked:fccLab.blocked,unknownButton:hass.states['button.fcc_memory_1'].state,capabilities:[before.attributes.supported_features,hass.states['cover.fcc_alternate'].attributes.supported_features]};
 });
 assert.equal(results.events.length,7);assert.equal(results.denied,6);assert.ok(results.restBlocked&&results.xhrBlocked);assert.equal(serviceFrames,0);assert.equal(serviceRequests,0);assert.equal(results.unknownButton,'unknown');assert.deepEqual(results.capabilities,[15,5]);
 const output={...results,serviceFramesSent:serviceFrames,serviceRequestsSent:serviceRequests,browser:browser.version(),fixtureCount:Object.keys(fixtures).length};
 await writeFile(area+'/fixtures.json',JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify({allowed:7,denied:6,serviceFrames,serviceRequests,unknownButton:results.unknownButton}));
} finally {await browser.close();}

