import {ws,base} from './common.mjs';
export const dashboard='fcc-candidate';
export async function prepare(page, config) {
 const list=await ws(page,{type:'lovelace/dashboards/list'});
 if(!list.some(x=>x.url_path===dashboard))await ws(page,{type:'lovelace/dashboards/create',url_path:dashboard,title:'Synthetic fixed composition candidate',mode:'storage',require_admin:true,show_in_sidebar:false});
 const resources=await ws(page,{type:'lovelace/resources'});
 if(!resources.some(x=>x.url==='/local/fixed-composition-card/card.js'))await ws(page,{type:'lovelace/resources/create',res_type:'module',url:'/local/fixed-composition-card/card.js'});
 await save(page,config);
}
export async function save(page,config) {
 await ws(page,{type:'lovelace/config/save',url_path:dashboard,config:{views:[
 {title:'Sections',path:'sections',type:'sections',max_columns:1,sections:[{type:'grid',cards:[config]}]},
 {title:'Masonry',path:'masonry',type:'masonry',cards:[config]}
 ]}});
}
export async function open(page,layout='sections') {
 await page.goto(`${base}/${dashboard}/${layout}`);
 await page.locator('#ha-launch-screen').waitFor({state:'hidden'});
 await page.locator('fixed-composition-card').first().waitFor();
 await page.locator('fixed-composition-card').first().evaluate(c=>{c.id='candidate';globalThis.fccCandidate=c;});
}

layout-check.mjs.source:
import assert from 'node:assert/strict';
import {mkdir,writeFile} from 'node:fs/promises';
import {openHA} from './common.mjs';
import {prepare,save,open} from './dashboard.mjs';
import {completeConfig,checkLayout} from '/root/workspace/ha-lovelace-extended/candidates/fixed-composition-card/test/runtime-browser.mjs';
const area='/root/research/ha-lovelace-extended/implement-complete-desk-composition';
await mkdir(area+'/screenshots',{recursive:true});
const results=[];
for(const language of ['en','pt-BR'])for(const theme of ['light','dark']) {
 const {browser,page}=await openHA({touch:true,language,colorScheme:theme});
 try {
  await prepare(page,completeConfig);
  for(const labels of ['ordinary','long']) {
   const config=labels==='ordinary'?completeConfig:{...completeConfig,name:'A long independent synthetic desk identity Supercalifragilisticexpialidocious',...Object.fromEntries([1,2,3].map(n=>[`action_${n}_label`,`Memory ${n} with a deliberately long label Pneumonoultramicroscopicsilicovolcanoconiosis`]))};
   await save(page,config);
   for(const layout of ['sections','masonry'])for(const viewport of [256,376,632])for(const scale of [1,2]) {
    await page.setViewportSize({width:viewport,height:900});await open(page,layout);
    const c=page.locator('#candidate');await c.evaluate((c,scale)=>{c.style.fontSize=16*scale+'px';},scale);
    await page.waitForFunction(({dark,language})=>fccCandidate.context.themes.darkMode===dark&&fccCandidate.context.language===language,{dark:theme==='dark',language});
    const name=`${language}-${theme}-${labels}-${layout}-${viewport}-${scale}`;
    const data=await checkLayout(page);
    const expected=viewport===632?(layout==='sections'?500:492):viewport-16;
    assert.equal(data.width,expected);assert.equal(data.font,16*scale+'px');
    await c.screenshot({path:area+'/screenshots/'+name+'.png'});
    const row={name,language,theme,labels,layout,viewport,scale,...data,pass:data.failures.length===0,screenshot:'screenshots/'+name+'.png'};
    results.push(row);await writeFile(area+'/layout.json',JSON.stringify(results,null,2)+'\n');
    if(!row.pass)throw new Error('Layout failed: '+JSON.stringify(row));
   }
  }
 } finally {await browser.close();}
}
console.log(JSON.stringify({cases:results.length,passed:results.filter(r=>r.pass).length,minimumWidth:Math.min(...results.map(r=>r.width))}));

