import assert from 'node:assert/strict';
export const initial={type:'custom:fixed-composition-card',primary_entity:'cover.fcc_primary',name:'Visually configured desk',icon:'mdi:desk',state_entity:'cover.fcc_primary',state_attribute:'current_position',height_entity:'sensor.fcc_height',height_attribute:'reading',open_target:'cover.fcc_primary',close_target:'cover.fcc_primary',stop_target:'cover.fcc_primary',position_target:'cover.fcc_primary',body_action:'more-info',body_target:'cover.fcc_primary',action_1_label:'Memory one',action_1_type:'press',action_1_target:'button.fcc_memory_1',action_2_label:'Memory two',action_2_type:'press',action_2_target:'button.fcc_memory_2',action_3_label:'Memory three',action_3_type:'press',action_3_target:'button.fcc_memory_3',confirm:false};
export const labels={primary_entity:'Primary cover',name:'Display name',icon:'Display icon',state_entity:'State source',state_attribute:'State attribute',height_entity:'Height source',height_attribute:'Height attribute',open_target:'Open target',close_target:'Close target',stop_target:'Stop target',position_target:'Position target',body_action:'Body action',body_target:'Body details target',confirm:'Confirm synthetic intent'};
for(let n=1;n<=3;n++){labels[`action_${n}_label`]=`Action ${n} label`;labels[`action_${n}_type`]=`Action ${n} type`;labels[`action_${n}_target`]=`Action ${n} target`;}
const friendly={'cover.fcc_primary':'Synthetic desk','cover.fcc_alternate':'Synthetic alternate','sensor.fcc_height':'Synthetic height','sensor.fcc_alternate':'Synthetic alternate height','button.fcc_memory_1':'Memory one','button.fcc_memory_2':'Memory two','button.fcc_memory_3':'Memory three'};
export async function editField(page,key,value) {
 const dialog=page.locator('hui-dialog-edit-card');const label=labels[key];
 if(key==='confirm'){const n=dialog.getByRole('switch',{name:label,exact:true});if(await n.isChecked()!==value)await n.press('Space');}
 else if(key==='icon'){
  await dialog.getByRole('button',{name:new RegExp('^'+label)}).click();
  const picker=page.getByRole('dialog',{name:label,exact:true});await picker.getByRole('textbox').fill(value);await picker.getByRole('option',{name:value,exact:true}).first().click();
 }
 else if(key==='body_action'||key.endsWith('_type')){
  const selector=dialog.locator('ha-selector-select').filter({has:page.getByRole('button',{name:new RegExp('^'+label+' ')})});
  await selector.getByRole('button',{name:new RegExp('^'+label+' ')}).click();
  await selector.getByRole('menuitem',{name:{none:'No action',press:'Button press','more-info':'Entity details'}[value],exact:true}).click();
 }
 else if(key.endsWith('_entity')||key.endsWith('_target')){
  await dialog.getByRole('button',{name:new RegExp('^'+label+' ')}).click();
  await page.getByRole('option',{name:new RegExp('^'+friendly[value]+' ')}).filter({has:page.getByText(friendly[value],{exact:true})}).click();
 }
 else {await dialog.getByRole('textbox',{name:label,exact:true}).fill(value);await page.keyboard.press('Tab');}
 await dialog.locator('ha-form').first().evaluate(form=>{globalThis.fccForm=form;});
 await page.waitForFunction(({key,value})=>globalThis.fccForm.data[key]===value,{key,value},{timeout:5000});
}
export async function assertForm(page,expected) {
 const data=await page.locator('hui-dialog-edit-card').locator('ha-form').first().evaluate(form=>form.data);
 assert.deepEqual(data,expected);
 for(const key of ['name','state_attribute','height_attribute','action_1_label','action_2_label','action_3_label'])assert.equal(await page.getByRole('textbox',{name:labels[key],exact:true}).inputValue(),expected[key]??'');
}

