import assert from 'node:assert/strict';
import {writeFile,readFile} from 'node:fs/promises';
import {openHA} from './common.mjs';
import {openExisting,saveVisual,storedCard} from './editor.mjs';
import {editField,assertForm} from './editor-fields.mjs';
const operations=[['primary_entity','cover.fcc_alternate'],['name','Independent visual edit'],['icon','mdi:table'],['state_entity','cover.fcc_alternate'],['state_attribute','friendly_name'],['height_entity','sensor.fcc_alternate'],['height_attribute','other_reading'],...['open','close','stop','position'].map(n=>[n+'_target','cover.fcc_alternate']),['body_action','none'],['body_target','sensor.fcc_height'],...[1,2,3].flatMap(n=>[[`action_${n}_label`,`Memory ${n} independently edited`],[`action_${n}_type`,'more-info'],[`action_${n}_target`,`button.fcc_memory_${n===3?1:n+1}`]]),['confirm',true],...[1,2,3].flatMap(n=>[[`action_${n}_type`,'none'],[`action_${n}_type`,'press']]),['body_action','more-info'],['confirm',false]];
const {browser,page}=await openHA();
const changes=[];
try {changes.push(...JSON.parse(await readFile('/root/research/ha-lovelace-extended/implement-complete-desk-composition/editor-roundtrip.json','utf8')).changes);} catch(error) {if(error.code!=='ENOENT')throw error;}
try{
 for(const [key,value]of operations.slice(changes.length)){
  const before=await storedCard(page);await openExisting(page);await assertForm(page,before);
  await editField(page,key,value);await saveVisual(page);
  const after=await storedCard(page);assert.deepEqual(after,{...before,[key]:value});
  await openExisting(page);await assertForm(page,after);
  await page.getByRole('button',{name:'Cancel',exact:true}).click();await page.getByRole('button',{name:'Done',exact:true}).click();
  const runtime=await page.locator('fixed-composition-card').first().evaluate(c=>({config:c.config,name:c.nodes.name.textContent,state:c.nodes.state.textContent,height:c.nodes.height.textContent,actual:c.nodes.actual.textContent,openDisabled:c.nodes.open.disabled,closeDisabled:c.nodes.close.disabled,stopDisabled:c.nodes.stop.disabled,labels:[1,2,3].map(n=>c.nodes[`action_${n}`].textContent),intentCount:c.sink.events.length}));
  assert.deepEqual(runtime.config,after);assert.equal(runtime.intentCount,0);
  if(key==='height_entity')assert.equal(runtime.height,'Height: 31.2 in');
  if(key==='height_attribute')assert.equal(runtime.height,'Height: 31.3 in');
  if(key==='close_target')assert.equal(runtime.closeDisabled,true);
  if(key==='stop_target')assert.equal(runtime.stopDisabled,true);
  if(key==='state_attribute')assert.equal(runtime.state,'State: Synthetic alternate');
  changes.push({key,value,before,after,untouchedPreserved:true,reopenedFormExact:true,runtime});
  await writeFile('/root/research/ha-lovelace-extended/implement-complete-desk-composition/editor-roundtrip.json',JSON.stringify({changes,complete:changes.length===operations.length},null,2)+'\n');
  console.log('Verified independent visual round trip:',key,value);
 }
}finally{await browser.close();}

