import assert from 'node:assert/strict';
import {ws,base,createPage} from './common.mjs';
import {completeConfig} from '/root/workspace/ha-lovelace-extended/candidates/fixed-composition-card/test/runtime-browser.mjs';
export const dashboard='fcc-candidate';
export const resource='/local/fixed-composition-card/card.js';
export const candidate={...completeConfig};
export function workload(variant,count) {
 const group=variant==='candidate'?[candidate]:variant==='empty'?[]:[
 {type:'tile',entity:'cover.fcc_primary',name:'Synthetic desk',features:[{type:'cover-open-close'},{type:'cover-position'}],features_position:'bottom',tap_action:{action:'more-info'},icon_tap_action:{action:'none'}},
 {type:'tile',entity:'sensor.fcc_height',name:'Direct height',tap_action:{action:'none'},icon_tap_action:{action:'none'}},
 ...[1,2,3].map(n=>({type:'tile',entity:`button.fcc_memory_${n}`,name:`Memory ${n}`,hide_state:true,tap_action:{action:'perform-action',perform_action:'button.press',target:{entity_id:`button.fcc_memory_${n}`}},icon_tap_action:{action:'none'}}))];
 return Array.from({length:count},()=>structuredClone(group)).flat();
}
export async function prepare(control,variant,count) {
 const resources=await ws(control,{type:'lovelace/resources'});
 for(const r of resources.filter(r=>r.url===resource))if(variant!=='candidate')await ws(control,{type:'lovelace/resources/delete',resource_id:r.id});
 if(variant==='candidate'&&!resources.some(r=>r.url===resource))await ws(control,{type:'lovelace/resources/create',res_type:'module',url:resource});
 await ws(control,{type:'lovelace/config/save',url_path:dashboard,config:{views:[{title:'Profile',path:'bench',type:'masonry',cards:workload(variant,count)}]}});
}
export async function ready(page,variant,count) {
 await page.locator('#ha-launch-screen').waitFor({state:'hidden'});
 await page.getByRole('button',{name:'Edit dashboard',exact:true}).waitFor();
 const selector=variant==='candidate'?'fixed-composition-card':'hui-tile-card';
 if(variant!=='empty') {
  await page.locator(selector).first().waitFor();
  await page.locator(selector).evaluateAll(async(nodes,{variant,count})=>{
   if(nodes.length!==(variant==='candidate'?count:count*5))throw new Error('Incomplete composition count');
   if(variant==='native')await Promise.all(nodes.map(n=>n.updateComplete));
   if(variant==='candidate'&&nodes.some(n=>!n.context.states['sensor.fcc_height']||n.nodes.height.textContent!=='Height: 83.5 cm'))throw new Error('Candidate data not ready');
  },{variant,count});
 } else assert.equal(await page.locator('hui-tile-card,fixed-composition-card').count(),0);
 await page.evaluate(async()=>{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});
}
export async function measuredPage(browser,auth,variant,count,{cold=true}={}) {
 const {context,page}=await createPage(browser,auth);
 const cdp=await context.newCDPSession(page);await cdp.send('Network.enable');await cdp.send('Performance.enable');
 if(cold)await cdp.send('Network.clearBrowserCache');
 await page.goto(`${base}/${dashboard}/bench`);await ready(page,variant,count);
 return {context,page,cdp};
}
export async function metrics(cdp){return Object.fromEntries((await cdp.send('Performance.getMetrics')).metrics.map(m=>[m.name,m.value]));}
export async function button(page,variant) {
 if(variant==='candidate')return page.locator('fixed-composition-card').first().locator('[data-role="action_1"]');
 if(variant==='native')return page.locator('hui-tile-card').nth(2).getByRole('button').first();
 await page.evaluate(()=>{globalThis.emptyInputJournal??=[];if(!document.querySelector('#driver-button')){const b=document.createElement('button');b.id='driver-button';b.textContent='Empty driver input';b.style.cssText='position:fixed;top:50px;right:8px;z-index:10000';b.addEventListener('click',()=>{globalThis.emptyInputJournal??=[];emptyInputJournal.push({target:'driver-only',recordedAt:performance.now()});});document.body.append(b);}});
 return page.locator('#driver-button');
}

