import assert from 'node:assert/strict';
import {writeFile} from 'node:fs/promises';
import {openHA,base} from './common.mjs';
import {prepare,measuredPage,button,ready,dashboard} from './profile-common.mjs';
const {browser,page:control,auth}=await openHA();const rows=[];
try {
 for(const count of [1,10])for(const variant of ['empty','native','candidate']) {
  await prepare(control,variant,count);const {context,page}=await measuredPage(browser,auth,variant,count);
  try{
   const resources=await page.evaluate(()=>performance.getEntriesByType('resource').filter(r=>r.name.includes('/fixed-composition-card/')).map(r=>new URL(r.name).pathname));
   assert.equal(resources.length>0,variant==='candidate');
   const dimensions=await page.locator(variant==='native'?'hui-tile-card':'fixed-composition-card').evaluateAll(nodes=>nodes.map(n=>({width:n.getBoundingClientRect().width,height:n.getBoundingClientRect().height})));
   const b=await button(page,variant);await b.click();
   const events=await page.evaluate(variant=>variant==='candidate'?document.querySelector('home-assistant')&&(()=>{const find=root=>{for(const e of root.querySelectorAll('*')){if(e.localName==='fixed-composition-card')return e;if(e.shadowRoot){const r=find(e.shadowRoot);if(r)return r;}}};return find(document).sink.events;})():variant==='native'?fccLab.events:emptyInputJournal,variant);
   assert.equal(events.length,1);
   if(variant==='native')assert.equal(events[0].target.entity_id,'button.fcc_memory_1');
   if(variant==='candidate')assert.equal(events[0].target,'button.fcc_memory_1');
   let coverControls=null;
   if(variant==='native'){
    coverControls=await page.locator('hui-tile-card').first().ariaSnapshot();
    assert.equal(await page.locator('hui-cover-open-close-card-feature').count(),count);
    assert.equal(await page.locator('hui-cover-position-card-feature').count(),count);
    const c=page.locator('hui-cover-open-close-card-feature').first();
    for(const label of ['Open cover','Close cover','Stop cover'])await c.getByRole('button',{name:label,exact:true}).click();
    assert.equal((await page.evaluate(()=>fccLab.events)).length,4);
   }
   const cold=await page.evaluate(()=>performance.getEntriesByType('resource').filter(r=>r.name.includes('/frontend_latest/')).reduce((a,r)=>a+r.transferSize,0));
   await page.reload();await ready(page,variant,count);
   const warm=await page.evaluate(()=>performance.getEntriesByType('resource').filter(r=>r.name.includes('/frontend_latest/')).reduce((a,r)=>a+r.transferSize,0));
   rows.push({variant,count,resources,dimensions,coldStaticTransfer:cold,warmStaticTransfer:warm,allowedInput:true,coverControls,allServiceTransportBlocked:true});
  }finally{await context.close();}
 }
 await writeFile('/root/research/ha-lovelace-extended/implement-complete-desk-composition/profile-preflight.json',JSON.stringify({rows,mismatches:['Native complete group uses five separate Tiles; candidate one card.','Native editor profile measures the cover Tile editor, not aggregate editing of all five Tiles.','Native position slider has native commit semantics; candidate uses release/Enter-only local preview.','Empty input is a driver-only button without HA service semantics.','Shared HA icon/dialog/editor costs remain in totals; no ownership or final-presentation attribution.']},null,2)+'\n');
 console.log(JSON.stringify({workloads:rows.length,preflight:'passed'}));
}finally{await browser.close();}

