import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {performance as clock} from 'node:perf_hooks';
import {openHA,base,createPage} from './common.mjs';
import {prepare,ready,measuredPage,metrics,button,dashboard} from './profile-common.mjs';
const area='/root/research/ha-lovelace-extended/implement-complete-desk-composition';
const phase=process.argv[2];
const pilot=process.argv.includes('--pilot');
const file=area+(pilot?'/profile-pilot-'+phase+'.json':'/profile-'+phase+'.json');
const samples=[];
await writeFile(file,JSON.stringify({phase,pilot,samples},null,2)+'\n',{flag:'wx'});
if(!pilot){const plan=JSON.parse(await readFile(area+'/profile-protocol.json','utf8'));for(const [path,hash]of Object.entries(plan.sourceHashes)){assert.equal(createHash('sha256').update(await readFile(path)).digest('hex'),hash,'Frozen source changed: '+path);}}
async function store(row){samples.push(row);await writeFile(file,JSON.stringify({phase,pilot,samples},null,2)+'\n');}
const {browser,page:control,auth}=await openHA();
const combinations=[];
for(const count of [1,10])for(const variant of ['empty','native','candidate'])combinations.push({variant,count});
const schedule=pilot?combinations.filter(c=>c.count===1):combinations;
const capture=async(page)=>page.evaluate(()=>({readyMs:performance.now(),resources:performance.getEntriesByType('resource').map(r=>({path:new URL(r.name).pathname,transfer:r.transferSize,encoded:r.encodedBodySize,decoded:r.decodedBodySize}))}));
async function resetFixture(entity='sensor.fcc_height',value='83.5') {
 const state=entity==='sensor.fcc_height'?{state:value,attributes:{friendly_name:'Synthetic height',unit_of_measurement:'cm',reading:Number(value),other_reading:83.6}}:{state:value,attributes:{friendly_name:'Unrelated profile source'}};
 const r=await fetch(`${base}/api/states/${entity}`,{method:'POST',headers:{Authorization:'Bearer '+auth.access_token,'Content-Type':'application/json'},body:JSON.stringify(state)});assert.ok(r.ok);return state;
}
async function updateWindow(page,cdp,{variant,count,rate,related,input=false}) {
 const duration=pilot?1000:10000,attempts=duration*rate/1000;
 const entity=related?'sensor.fcc_height':'sensor.fcc_unrelated';
 await resetFixture();await resetFixture('sensor.fcc_unrelated','0');
 await page.waitForTimeout(200);
 await page.evaluate(async entity=>{globalThis.profileReceived=[];globalThis.profileUnsubscribe=await document.querySelector('home-assistant').hass.connection.subscribeEvents(event=>{if(event.data.entity_id===entity)profileReceived.push(event.data.new_state.state);},'state_changed');},entity);
 const cpuBefore=await metrics(cdp);const start=clock.now();const late=[];const delivered=[];
 const update=(async()=>{
  for(let i=0;i<attempts;i++){
   const due=start+i*1000/rate;await new Promise(r=>setTimeout(r,Math.max(0,due-clock.now())));late.push(clock.now()-due);
   const value=String(84+i/10);await resetFixture(entity,value);delivered.push(value);
  }
  await new Promise(r=>setTimeout(r,Math.max(0,start+duration-clock.now())));
 })();
 const inputs=input?await inputTrials(page,variant,pilot?2:10,start,duration):null;
 await update;
 const last=delivered.at(-1);
 await page.waitForFunction(({entity,last})=>document.querySelector('home-assistant').hass.states[entity]?.state===last,{entity,last});
 const final=await page.evaluate(entity=>document.querySelector('home-assistant').hass.states[entity].state,entity);
 const cpuAfter=await metrics(cdp);
 const received=await page.evaluate(()=>{profileUnsubscribe();return profileReceived;});
 assert.equal(received.length,attempts);assert.equal(received.at(-1),last);
 const result={variant,count,rate,related,input,scheduledDurationMs:duration,elapsedMs:clock.now()-start,attempts,successfulPosts:delivered.length,browserReceived:received.length,final,last,latenessMs:late,scriptSeconds:cpuAfter.ScriptDuration-cpuBefore.ScriptDuration,taskSeconds:cpuAfter.TaskDuration-cpuBefore.TaskDuration,inputs,valid:final===last&&delivered.length===attempts};
 await resetFixture();return result;
}
async function inputTrials(page,variant,number,start=null,duration=0){
 const target=await button(page,variant);
 await page.evaluate(variant=>{
  globalThis.activationStart=null;globalThis.localInputSamples=[];
  if(!globalThis.fccInputObserver){document.addEventListener('pointerdown',()=>{activationStart=performance.now();},{capture:true});globalThis.fccInputObserver=true;}
  let journal;
  if(variant==='candidate'){
   const find=root=>{for(const e of root.querySelectorAll('*')){if(e.localName==='fixed-composition-card')return e;if(e.shadowRoot){const v=find(e.shadowRoot);if(v)return v;}}};journal=find(document).sink.events;
  }else journal=variant==='native'?fccLab.events:emptyInputJournal;
  journal.length=0;
  journal.push=function(...events){for(const event of events)localInputSamples.push({start:activationStart,recordedAt:performance.now(),target:event.target?.entity_id??event.service_data?.entity_id??event.target,origin:event.origin??'native-or-driver'});return Array.prototype.push.apply(this,events);};
 },variant);
 const lateness=[];
 for(let i=0;i<number;i++){
  if(start!==null){const due=start+duration*(i+.5)/number;await new Promise(r=>setTimeout(r,Math.max(0,due-clock.now())));lateness.push(clock.now()-due);}
  await target.click({timeout:5000});
  await page.waitForFunction(n=>localInputSamples.length===n,i+1,{timeout:5000});
 }
 const rows=await page.evaluate(()=>localInputSamples.map(r=>({...r,localIntentMs:r.recordedAt-r.start})));
 assert.equal(rows.length,number);for(const row of rows){assert.ok(Number.isFinite(row.localIntentMs)&&row.localIntentMs>=0);assert.equal(row.target,variant==='empty'?'driver-only':'button.fcc_memory_1');}
 return {number,rows,latenessMs:lateness};
}
async function editorPair(page,cdp,variant,count,trial){
 const rows=[];
 for(const phase of ['first-open','same-document-reopen']){
  const cpuBefore=await metrics(cdp);const resourceStart=await page.evaluate(()=>performance.getEntriesByType('resource').length);
  const start=await page.evaluate(()=>performance.now());await page.getByRole('button',{name:'Edit dashboard',exact:true}).click();
  if(variant!=='empty'){
   await page.getByRole('button',{name:/^Edit(?: card)?$/}).first().press('Enter');
   if(variant==='candidate')await page.getByRole('textbox',{name:'Display name',exact:true}).waitFor();
   else await page.locator('hui-tile-card-editor').evaluate(e=>e.updateComplete);
  }
  await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));
  const elapsed=await page.evaluate(start=>performance.now()-start,start);
  const cpuAfter=await metrics(cdp);const resources=await page.evaluate(index=>performance.getEntriesByType('resource').slice(index).map(r=>({path:new URL(r.name).pathname,transfer:r.transferSize,encoded:r.encodedBodySize,decoded:r.decodedBodySize})),resourceStart);
